// Fast index lookup by word / lemma
const SENTENCES_BY_WORD_MAP: Map<string, ExampleSentence[]> = new Map();

for (const s of EXAMPLE_SENTENCES) {
  if (s.word) {
    const existing = SENTENCES_BY_WORD_MAP.get(s.word);
    if (existing) {
      existing.push(s);
    } else {
      SENTENCES_BY_WORD_MAP.set(s.word, [s]);
    }
  }
}

/**
 * Get all example sentences illustrating a specific vocabulary word
 */
export function getSentencesForWord(word: string): ExampleSentence[] {
  if (!word) return [];
  const clean = word.trim();
  const direct = SENTENCES_BY_WORD_MAP.get(clean);
  if (direct && direct.length > 0) return direct;

  // Partial search if exact match not found
  return EXAMPLE_SENTENCES.filter((s) => s.ja.includes(clean)).slice(0, 5);
}

/**
 * Filter sentences by category and optional query
 */
export function querySentences(params: {
  category?: string;
  query?: string;
  limit?: number;
  offset?: number;
}): { items: ExampleSentence[]; total: number } {
  const { category, query, limit = 50, offset = 0 } = params;
  let results = EXAMPLE_SENTENCES;

  if (category && category !== "All") {
    results = results.filter((s) => s.category === category);
  }

  if (query && query.trim()) {
    const q = query.trim().toLowerCase();
    results = results.filter(
      (s) =>
        s.ja.toLowerCase().includes(q) ||
        s.en.toLowerCase().includes(q) ||
        s.romaji.toLowerCase().includes(q) ||
        s.word.toLowerCase().includes(q)
    );
  }

  const total = results.length;
  const items = results.slice(offset, offset + limit);
  return { items, total };
}
